import org.junit.Test;
import static org.junit.Assert.*;

public class DateTimeFormatter_parseInto_TriageGen0Test {

    /**
     * Test that passing a null instant throws IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendInstant().getFormatter();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    /**
     * Test successful parsing of a date string into a ReadWritableInstant.
     * This covers the standard execution path.
     */
    @Test
    public void testParseInto_Success() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonth()
                .appendLiteral('-')
                .appendDayOfMonth()
                .getFormatter();

        MutableDateTime instant = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        String text = "2023-05-10";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        // Verify position advancement (Year(4) + '-' (1) + Month(2) + '-' (1) + Day(2) = 10)
        // Note: The parser behavior depends on the specific DateTimeParser implementation.
        // Assuming standard Joda behavior where it returns the next index.
        Assert.assertTrue("New position should be greater than old position", newPos > position);
        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(5, instant.getMonthOfYear());
        Assert.assertEquals(10, instant.getDayOfMonth());
    }

    /**
     * Test parsing with offset support enabled.
     * Covers the branch: if (iOffsetParsed && bucket.getOffsetInteger() != null)
     */
    @Test
    public void testParseInto_WithOffsetParsed() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonth()
                .appendLiteral('-')
                .appendDayOfMonth()
                .appendLiteral(' ')
                .appendHourOfDay()
                .appendLiteral(':')
                .appendMinuteOfHour()
                .appendLiteral('+')
                .appendOffset("+HH:mm")
                .toFormatter()
                .withOffsetParsed();

        MutableDateTime instant = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        String text = "2023-01-01 12:00+05:00";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(12, instant.getHourOfDay());
        Assert.assertEquals(0, instant.getMinuteOfHour());
        // Check if zone was updated by the offset
        Assert.assertEquals("+05:00", instant.getZone().getID());
    }

    /**
     * Test parsing where a zone is provided by the bucket but offset parsing is disabled.
     * Covers the branch: else if (bucket.getZone() != null)
     */
    @Test
    public void testParseInto_WithBucketZone() {
        // Using a pattern that might contain zone info if supported by the parser
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonth()
                .appendLiteral('-')
                .appendDayOfMonth()
                .getFormatter();

        MutableDateTime instant = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        // Force a specific chronology/zone via the instant to test interaction
        instant.setZone(DateTimeZone.forID("UTC"));

        String text = "2023-01-01";
        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(2023, instant.getYear());
    }

    /**
     * Test that setting a specific zone on the formatter overrides the parsed zone.
     * Covers the branch: if (iZone != null)
     */
    @Test
    public void testParseInto_WithFixedZone() {
        DateTimeZone fixedZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonth()
                .appendLiteral('-')
                .appendDayOfMonth()
                .getFormatter()
                .withZone(fixedZone);

        MutableDateTime instant = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        String text = "2023-01-01";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(fixedZone, instant.getZone());
    }

    /**
     * Test parsing with a specific locale.
     */
    @Test
    public void testParseInto_WithLocale() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendMonthText(java.time.format.TextStyle.FULL)
                .appendDayOfMonth()
                .appendLiteral(',')
                .appendYear()
                .getFormatter()
                .withLocale(Locale.FRENCH);

        MutableDateTime instant = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        // "janvier" is French for January
        String text = "janvier 01, 2023";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(1, instant.getMonthOfYear());
        Assert.assertEquals(2023, instant.getYear());
    }
}
